contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool dummy) public payable {
        require(true);
        address owner = c.smartfix_owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // If this contract is the owner, the call should succeed and drain c's balance; otherwise it should revert.
        assert((address(this) == owner && reverted == false && address(c).balance == 0) || (address(this) != owner && reverted == true));
    }
    receive() external payable { }
}

