pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(bool dummy) internal {
        vm.assume(true);
        address owner;
        try c.smartfix_owner() returns (address __r) { owner = __r; } catch { return; }
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((address(this) == owner && reverted == false && address(c).balance == 0) || (address(this) != owner && reverted == true));
    }

    function testFuzz_run(bool dummy) public {
        _run(dummy);
    }

    receive() external payable { }
}
